-- İHA Elektronik Sistemleri (T3 7.1, 7.3, 8.1, 8.2) altyazıları: 1ccR99OhHT8, R4XNBVH7PF8, fYbItD4Rwps, DHWzZNyhXSY. (7.2 Motor videosu oynatılamadığı için alınamadı.)
-- Kaynak: oynatıcının otomatik Türkçe altyazısı (hızlı oynatılıp toplandı; ASR hataları olabilir).
-- Her sorunun kaynak video id ve altyazıdan alıntısı aşağıdaki yorumlardadır.
-- İHA Elektronik Sistemleri orta/zor quizlerine EKLENİR. Idempotent: aynı soru metni varsa atlanır.

begin;

-- 1ccR99OhHT8 kaynak: itki, güç sistemi, kontrol ve servo sistemleri, uçuş kontrol bilgisayarı, görev bilgisayarı.
-- 1ccR99OhHT8 kaynak: Elektrikli motorlar hafiflikleri, yüksek verimlilikleri ve düşük bakım gereksinimleri nedeniyle küçük ve orta ölçekli İHA'larda yaygın olarak tercih edilir.
-- 1ccR99OhHT8 kaynak: Çoğu İHA lityum iyon ve lityum polimer bataryalarla çalışır. Bu bataryalar hafif olmaları ve yüksek enerji yoğunlukları sayesinde uzun uçuş süresi sağlar.
-- 1ccR99OhHT8 kaynak: Kanatçık, irtifa dümeni ve yön dümeni gibi kontrol yüzeyleri servo motorlar aracılığıyla hareket ettirilerek uçuş manevraları gerçekleştirilir.
-- R4XNBVH7PF8 kaynak: Her hücre yaklaşık olarak 3.7 volt nominal gerilime sahiptir. Tam dolu bir hücre ise 4.2 volt değerine sahiptir. Örneğin 3S batarya 3.7 x 3'ten 11.1 volt nominal voltaja sahiptir.
-- fYbItD4Rwps kaynak: Küresel navigasyon uydu sistemi, dünya genelinde konum belirleme, navigasyon ve zaman senkronizasyonu sağlayan uydu tabanlı sistemlerin genel adıdır... GPS, GLONASS, Galileo ve BeiDou... en yaygın olanı Amerika'ya ait GPS'tir.
-- DHWzZNyhXSY kaynak: GPS dünya yörüngesindeki uydular aracılığıyla enlem, boylam ve yükseklik bilgilerini alarak İHA'nın nerede olduğunu belirler. RTK ile konum verileri 1 ila 2 cm hassasiyetine kadar ulaşabilir.
do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'İHA Elektronik Sistemleri' and z.zorluk = 'orta' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: İHA Elektronik Sistemleri orta'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Videoya göre İHA elektronik sistemleri hangi başlıklar altında incelenir? (birden çok)","a":"Kontrol ve servo sistemleri de bu başlıklar arasındadır.","o":[["İtki (motor ve pervane) sistemi",true],["Güç sistemi",true],["Uçuş kontrol bilgisayarı ve görev bilgisayarı",true],["Kabin basınçlandırma sistemi",false]]},{"m":"Elektrikli motorlar küçük ve orta ölçekli İHA'larda neden yaygın tercih edilir?","a":"İtki sistemi elektrikli veya içten yanmalı motorlarla sağlanır.","o":[["Hafif, yüksek verimli ve düşük bakım gerektirdikleri için",true],["Çok daha güçlü oldukları için",false],["Yakıt kullandıkları için",false],["Daha ucuz yakıt kullandıkları için",false]]},{"m":"Videoya göre çoğu İHA'da hangi bataryalar kullanılır ve neden?","a":"Güç sistemi motor tipine ve uçuş süresi gereksinimine göre değişir.","o":[["Lityum iyon ve lityum polimer; hafif ve yüksek enerji yoğunluklu oldukları için uzun uçuş süresi sağlarlar",true],["Kurşun asit; ucuz oldukları için",false],["Nikel-kadmiyum; dayanıklı oldukları için",false],["Alkali piller; kolay bulundukları için",false]]},{"m":"Kontrol yüzeyleri (kanatçık, irtifa ve yön dümeni) nasıl hareket ettirilir?","a":"Kontrol sistemleri İHA'nın yönünü, dengesini ve kontrol yüzeylerinin hareketini belirler.","o":[["Servo motorlar aracılığıyla",true],["Doğrudan ana motorla",false],["Pervane hızıyla",false],["Batarya ağırlığını kaydırarak",false]]},{"m":"Videoya göre LiPo hücresinin nominal ve tam dolu gerilimi ile 3S bataryanın nominal gerilimi nedir?","a":"Hücre sayısı bataryanın gerilimini belirler.","o":[["Hücre 3,7 V nominal, 4,2 V tam dolu; 3S batarya 11,1 V",true],["Hücre 1,5 V nominal; 3S batarya 4,5 V",false],["Hücre 4,2 V nominal; 3S batarya 12,6 V",false],["Hücre 3,7 V tam dolu; 3S batarya 7,4 V",false]]},{"m":"Videoya göre GNSS nedir?","a":"En yaygın GNSS sistemi ABD'ye ait GPS'tir.","o":[["Konum, navigasyon ve zaman senkronizasyonu sağlayan uydu tabanlı sistemlerin genel adı (GPS, GLONASS, Galileo, BeiDou)",true],["Yalnızca Amerika'nın GPS sistemi",false],["Bir tür batarya",false],["Radyo kontrol protokolü",false]]},{"m":"Videoya göre GPS hangi bilgileri sağlar ve RTK ile hassasiyet ne seviyeye ulaşabilir?","a":"Enlem ve boylam verileri derece cinsinden gönderilir.","o":[["Enlem, boylam ve yükseklik; RTK ile 1-2 cm hassasiyete kadar",true],["Yalnızca yön; 1 m hassasiyete kadar",false],["Hız ve ivme; 10 m hassasiyete kadar",false],["Yalnızca zaman; 50 cm hassasiyete kadar",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

-- 1ccR99OhHT8 kaynak: Uçuş kontrol bilgisayarı otonom uçuş, rota planlama ve acil durum yönetimi... sensörlerden gelen verileri analiz eder ve motorlara ya da kontrol yüzeylerine gerekli komutları gönderir. Görev bilgisayarı keşif, haritalama, hedef takibi veya kargo taşımacılığı gibi görevler için özelleştirilmiş algoritmalar içerir; Jetson veya Raspberry.
-- R4XNBVH7PF8 kaynak: Lityum polimer bataryalar hafif ve yüksek enerji yoğunluğuna sahiptir, yüksek deşarj kapasitesi sunar. Lityum iyon bataryalar lipo bataryalara kıyasla daha düşük deşarj oranına sahiptir, ancak daha uzun ömürlüdür, daha uzun uçuş süreleri için tercih edilir.
-- R4XNBVH7PF8 kaynak: Deşarj oranı bataryanın ne kadar hızlı deşarj olabileceğini gösteren katsayıdır. Batarya kapasitesi ile birlikte değerlendirilerek anlık sağlayabileceği maksimum akım değerini gösterir. Akım değeri deşarj oranı ile pil kapasitesinin çarpımı ile elde edilir.
-- R4XNBVH7PF8 kaynak: Bataryanın toplam kapasitesini aracın çektiği akım miktarına bölüp 60 ile çarptığımızda tahmini uçuş süresini elde ederiz. İki motorlu bir İHA'nın her motoru 20 amper çekerse toplam 40 amper, yani 40.000 miliamper; 5000 mAh ile uçuş süremiz 7,5 dakika olur.
-- R4XNBVH7PF8 kaynak: Bu hesaplama ideal koşullar içindir. Gerçek uçuş süresi hava koşulları, ağırlık ve pil verimliliğine bağlı olarak değişebilir. Yüksek akım çeken motorlar için daha yüksek C değerine sahip bataryalar... bataryanızın fazla ağır olmamasına dikkat edin.
-- fYbItD4Rwps kaynak: İHA'lar hava sahasında güvenli bir şekilde hareket edebilmek için daha düşük gecikmeli ve santimetre seviyesinde doğruluk sağlayan sistemlere ihtiyaç duyuyor. Bu yüzden RTK ve diğer düzeltme yöntemleriyle GNSS sinyalleri daha hassas hale getiriliyor.
-- fYbItD4Rwps kaynak: Yüksek binalar, yoğun ağaçlık alanlar veya atmosferik koşullar sinyali bozabilir. Bu yüzden çoklu GNSS sistemleri ve RTK gibi teknolojiler hassasiyeti artırarak hataları en aza indirir.
-- DHWzZNyhXSY kaynak: GPS modülünün İHA dışına yerleştirilmesi sinyal parazitlenmesini önleyecektir. Manyetik alanı etkileyen karbon fiber ve metal gibi gövde malzemesi GPS sinyallerini zayıflatabilir. Bu da hassasiyetin düşmesine neden olur.
-- DHWzZNyhXSY kaynak: Manyetometre dünyanın manyetik alanını algılayarak cihazların hangi yöne baktığını belirler... üç eksende (X, Y, Z) manyetik alanı ölçerek yön tahmini yapar. Otopilot manyetometreden alınan veriyi işleyerek İHA'nın yön açısını belirler.
-- DHWzZNyhXSY kaynak: pusula kalibrasyonu manyetik alan hatalarını gidermek ve doğru yönü belirlemek için yapılır. Bu işlem sırasında aracın döndürülmesi manyetik alanın tüm eksenlerde doğru şekilde ölçülmesini sağlar.
-- DHWzZNyhXSY kaynak: yüksek akım çeken güç sistemlerinden yani motorlar, ESC'ler, batarya kabloları gibi bileşenlerden uzağa monte edilmesi gereklidir. Manyetik parazitler pusula ölçümlerinde sapmalara neden olarak yanlış yön bilgisi üretilmesine yol açabilir.
-- DHWzZNyhXSY kaynak: Otopilot kartının içinde bulunan IMU sensörü diğer sensörler ile çalışarak elde ettiği verilere göre İHA'yı kontrol eder. Sensörlerin bu şekilde bir arada ve birbirleriyle bağımlı çalışmasına sensör füzyonu denir.
do $q$
declare v_quiz uuid; v_q uuid; v_sira int; r jsonb; o jsonb; j int;
begin
  select z.id into v_quiz from public.quizzes z join public.modules m on m.id = z.module_id
   where m.ad = 'İHA Elektronik Sistemleri' and z.zorluk = 'zor' limit 1;
  if v_quiz is null then raise notice 'Quiz yok, atlanıyor: İHA Elektronik Sistemleri zor'; return; end if;
  select coalesce(max(sira), 0) into v_sira from public.questions where quiz_id = v_quiz;
  for r in select * from jsonb_array_elements($json$[{"m":"Uçuş kontrol bilgisayarı ile görev bilgisayarı arasındaki fark videoda nasıl anlatılır?","a":"Görev bilgisayarı sensör ve kamera verilerini analiz edip operatöre veya uçuş kontrol bilgisayarına bilgi iletir.","o":[["Uçuş kontrol bilgisayarı uçuşu yönetir (otonom uçuş, rota planlama, acil durum, motor/kontrol yüzeyi komutları); görev bilgisayarı göreve özel algoritmalar çalıştırır (keşif, haritalama, hedef takibi; Jetson, Raspberry)",true],["İkisi aynı işi yapar",false],["Görev bilgisayarı motorları sürer, uçuş kontrol kamerayı işler",false],["Uçuş kontrol bilgisayarı yalnızca bataryayı izler",false]]},{"m":"LiPo ve Li-ion bataryaların karşılaştırması videoda nasıl yapılır?","a":"Li-ion yüksek akım gerektiren uygulamalarda LiPo kadar verimli değildir.","o":[["LiPo: hafif, yüksek enerji yoğunluğu, yüksek deşarj (güçlü motorlar); Li-ion: düşük deşarj oranı ama daha uzun ömürlü ve uzun uçuş süresi için uygun",true],["Li-ion yüksek deşarj sunar, LiPo daha uzun ömürlüdür",false],["İkisi de aynı deşarj oranına sahiptir",false],["LiPo yalnızca küçük İHA'larda kullanılır",false]]},{"m":"Bataryanın anlık sağlayabileceği maksimum akım nasıl hesaplanır?","a":"Örneğin 5000 mAh ve 20C bir batarya teorik olarak 100 A verebilir.","o":[["Deşarj oranı (C) x kapasite",true],["Kapasite / deşarj oranı",false],["Gerilim x hücre sayısı",false],["Kapasite / uçuş süresi",false]]},{"m":"Her motoru 20 A çeken iki motorlu bir İHA'da 5000 mAh batarya ile tahmini uçuş süresi nedir?","a":"Süre = kapasite / toplam akım x 60 = 5000 / 40000 x 60 = 7,5 dk. Hesap ideal koşulludur.","o":[["7,5 dakika",true],["15 dakika",false],["2,5 dakika",false],["30 dakika",false]]},{"m":"Batarya seçerken videodaki öneriler hangileridir? (birden çok)","a":"Ağır batarya motorların daha fazla enerji tüketmesine neden olabilir ve uçuş süresini olumsuz etkileyebilir.","o":[["Motor ve ESC gereksinimine uygun voltajda batarya",true],["Yüksek akım çeken motorlar için daha yüksek C değerli batarya",true],["Daha uzun süre için daha yüksek mAh, ama ağırlığa dikkat",true],["Ağırlığı hiç dikkate almamak",false]]},{"m":"İHA'lar telefonlardaki GPS'ten neden daha hassas sistemlere ihtiyaç duyar?","a":"Arabalardaki navigasyonla aynı prensipte çalışırlar, ama İHA'lar daha hassas konuma ve gelişmiş sensörlere ihtiyaç duyar.","o":[["Hava sahasında güvenli hareket için düşük gecikmeli ve santimetre seviyesinde doğruluk gerektiği için; RTK ve düzeltme yöntemleri kullanılır",true],["Telefonlar GPS kullanmadığı için",false],["İHA'lar daha yavaş uçtuğu için",false],["Gürültüyü azaltmak için",false]]},{"m":"GNSS sinyalini bozan etkenler ve çözümleri videoda nasıl anlatılır? (birden çok doğru)","a":"Bu nedenle tek bir sisteme güvenmek yerine çoklu GNSS ve düzeltme teknolojileri kullanılır.","o":[["Yüksek binalar ve yoğun ağaçlık alanlar sinyali bozabilir",true],["Atmosferik koşullar sinyali bozabilir",true],["Çoklu GNSS sistemleri ve RTK hataları azaltır",true],["GNSS sinyali hiçbir koşulda bozulmaz",false]]},{"m":"GPS modülünün yerleşimi için videoda ne önerilir ve neden?","a":"Sinyal parazitlenmesi önlenerek daha güvenilir veri iletimi sağlanır.","o":[["Gövde dışına/uzağa yerleştirilmeli; karbon fiber ve metal gibi malzemeler sinyali zayıflatıp hassasiyeti düşürür",true],["Bataryanın hemen yanına konmalı",false],["Metal gövdenin içine gömülmeli",false],["Yerleşimin etkisi yoktur",false]]},{"m":"Manyetometre (pusula) İHA'da ne yapar?","a":"GPS yönü belirlemek için tek başına yeterli değildir.","o":[["Dünyanın manyetik alanını X, Y, Z üç ekseninde ölçerek İHA'nın baş (yön) açısını belirler",true],["Konumu enlem-boylam olarak verir",false],["Hızı ölçer",false],["Batarya gerilimini ölçer",false]]},{"m":"Pusula kalibrasyonunda araç neden döndürülür?","a":"Böylece pusula daha sağlıklı ölçümler yapar.","o":[["Manyetik alanın tüm eksenlerde doğru ölçülmesini sağlayıp manyetik alan hatalarını gidermek için",true],["Pili şarj etmek için",false],["GPS'i hızlandırmak için",false],["Motorları ısıtmak için",false]]},{"m":"Pusula (manyetometre) nereye monte edilmelidir?","a":"Pusula GPS modülüne entegre olabilir veya otopilotun içinde yer alabilir.","o":[["Motorlar, ESC'ler ve batarya kabloları gibi yüksek akım çeken parçalardan uzağa",true],["Motorların hemen yanına",false],["Batarya kablolarının üzerine",false],["ESC'nin altına",false]]},{"m":"Videoya göre sensör füzyonu nedir?","a":"GPS konumu, pusula yönü belirler; füzyon kontrolü daha kararlı yapar.","o":[["IMU ve GPS, pusula gibi sensörlerin birbirine bağlı çalışıp verilerini birleştirerek aracı daha kararlı kontrol etmesi",true],["Sensörlerin tek bir parça halinde üretilmesi",false],["Yalnızca GPS verisinin kullanılması",false],["Sensörlerin kapatılması",false]]}]$json$::jsonb) loop
    if exists (select 1 from public.questions where quiz_id = v_quiz and metin = r->>'m') then continue; end if;
    v_sira := v_sira + 1;
    insert into public.questions (quiz_id, metin, sira, aciklama)
      values (v_quiz, r->>'m', v_sira, r->>'a') returning id into v_q;
    j := 0;
    for o in select * from jsonb_array_elements(r->'o') loop
      j := j + 1;
      insert into public.question_options (question_id, metin, dogru, sira)
        values (v_q, o->>0, (o->>1)::boolean, j);
    end loop;
  end loop;
end $q$;

commit;
